use serde_json::Value;

fn rot13(c: char) -> char {
    match c {
        'a'..='z' => ((c as u8 - b'a') + 13) % 26 + b'a' as char,
        'A'..='Z' => ((c as u8 - b'A') + 13) % 26 + b'A' as char,
        _ => c,
    }
}

fn transform_string(s: &str) -> String {
    s.chars().map(rot13).collect()
}

fn transform_value(value: &Value) -> Value {
    match value {
        Value::String(s) => Value::String(transform_string(s)),
        Value::Array(arr) => Value::Array(arr.iter().map(transform_value).collect()),
        Value::Object(obj) => Value::Object(
            obj.iter()
                .map(|(k, v)| (k.clone(), transform_value(v)))
                .collect(),
        ),
        _ => value.clone(),
    }
}

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    transform_value(&input)
}
